// Experience describes what survives a new development life. It is not cash.
export const EXPERIENCE_TYPES = [
  { id: 'craft', name: '制作経験' },
  { id: 'design', name: '設計の勘' },
  { id: 'audience', name: '遊びの発見' }
];
export const emptyExperience = () => ({ craft: 0, design: 0, audience: 0 });
export const EXPERIENCE_REWARDS = [
  { craft: 2, design: 0, audience: 0 },
  { craft: 3, design: 2, audience: 1 },
  { craft: 6, design: 5, audience: 6 },
  { craft: 14, design: 16, audience: 18 },
  { craft: 32, design: 40, audience: 50 },
  { craft: 80, design: 100, audience: 140 },
  { craft: 200, design: 280, audience: 350 }
];
export function experienceReward(index) {
  if (EXPERIENCE_REWARDS[index]) return { ...EXPERIENCE_REWARDS[index] };
  const scale = Math.min(1e200, 3 ** Math.min(400, index - 6));
  return { craft: 200 * scale, design: 280 * scale, audience: 350 * scale };
}
export function experienceCap(index){
  if(index<2)return null;
  if(index===2)return {craft:60,design:40,audience:60};
  const limit=Math.min(1e250,240*5**Math.min(400,index-3));
  return {craft:limit,design:limit,audience:limit};
}
export function experienceEffects(experience = emptyExperience()) {
  const craft = Math.max(0, experience.craft || 0), design = Math.max(0, experience.design || 0), audience = Math.max(0, experience.audience || 0);
  return { speed: 1 + Math.sqrt(craft) * .35, planning: 1 + Math.sqrt(audience) * .3, architecture: 1 / (1 + Math.sqrt(design) * .15), audience: 1 + Math.sqrt(audience) * .3 };
}
export function experienceRequirements(index) {
  if (index < 2) return { experience: emptyExperience(), items: {} };
  if (index === 2) return { experience: { craft: 5, design: 2, audience: 1 }, items: {} };
  if (index === 3) return { experience: { craft: 25, design: 18, audience: 20 }, items: { engineer: 1, library: 1 } };
  if (index === 4) return { experience: { craft: 160, design: 120, audience: 100 }, items: { engineer: 3, library: 3, cluster: 1 } };
  const scale = Math.min(1e200, 3 ** Math.min(400, index - 4));
  return { experience: { craft: 160 * scale, design: 120 * scale, audience: 100 * scale }, items: { engineer: index - 1, library: index - 1, cluster: index - 3 } };
}
export const salesTerms = index => index < 2 ? { price: 0, copies: 0, halfLife: 3600 } : [
  null, null,
  { price: 500, copies: 40, halfLife: 3600 },
  { price: 1500, copies: 1000, halfLife: 4 * 3600 },
  { price: 6000, copies: 30000, halfLife: 12 * 3600 },
  { price: 3000, copies: 2000000, halfLife: 24 * 3600 },
  { price: 6000, copies: 1e9, halfLife: 48 * 3600 }
][index] || { price: 10000, copies: Math.min(1e240, 1e11 * 50 ** Math.min(100, index - 7)), halfLife: 72 * 3600 };
export const remainingSales = title => Array.isArray(title.salesBatches) ? title.salesBatches.reduce((sum,b)=>sum+Math.max(0,b.remaining || 0),0) : Math.max(0, title.salesRemaining || 0);
export const titleSalesRate = title => title.active === false ? 0 : Array.isArray(title.salesBatches) ? title.salesBatches.reduce((sum,b)=>sum+(b.active===false?0:Math.max(0,b.remaining || 0)*Math.LN2/Math.max(1,b.halfLife || 3600)),0) : remainingSales(title) * Math.LN2 / Math.max(1, title.salesHalfLife || 3600);
export const salesDuring = (title, seconds) => title.active === false ? 0 : Array.isArray(title.salesBatches) ? title.salesBatches.reduce((sum,b)=>sum+(b.active===false?0:Math.max(0,b.remaining || 0)*-Math.expm1(-Math.LN2*Math.max(0,seconds)/Math.max(1,b.halfLife || 3600))),0) : remainingSales(title) * -Math.expm1(-Math.LN2 * Math.max(0, seconds) / Math.max(1, title.salesHalfLife || 3600));
export function settleSales(title,seconds){
  const sold=salesDuring(title,seconds);
  let copies=title.unitPrice?sold/title.unitPrice:0;
  if(Array.isArray(title.salesBatches)){
    copies=0;
    if(title.active!==false)for(const batch of title.salesBatches){
      if(batch.active===false)continue;
      const amount=Math.max(0,batch.remaining || 0)*-Math.expm1(-Math.LN2*Math.max(0,seconds)/Math.max(1,batch.halfLife || 3600));
      batch.remaining=Math.max(0,batch.remaining-amount);
      if(batch.unitPrice)copies+=amount/batch.unitPrice;
    }
  }
  title.salesRemaining=Math.max(0,remainingSales(title)-(title.salesBatches?0:sold));
  title.soldCopies=Math.min(title.totalCopies || 0,(title.soldCopies || 0)+copies);
  title.salesEarned=Math.min(1e250,(title.salesEarned || 0)+sold);
  title.royalty=titleSalesRate(title);
  return sold;
}
